-- CEMP v0.8.0: integration API (darkwizscroll, DARKWIZ CT) + content search.
-- API keys are generated by the app and only their SHA-256 hash is stored here.

create table public.api_clients (
  id smallint generated always as identity primary key,
  name text not null unique,
  key_prefix text not null,
  key_hash text not null unique check (key_hash ~ '^[0-9a-f]{64}$'),
  scopes text[] not null default '{content,calc}',
  active boolean not null default true,
  created_at timestamptz not null default now(),
  last_used_at timestamptz
);
alter table public.api_clients enable row level security;
create policy api_clients_admin on public.api_clients for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));

-- Internal: validate a key hash + scope, stamp last use. Not callable by clients directly.
create or replace function public.api_client_ok(p_key_hash text, p_scope text)
returns boolean language plpgsql security definer set search_path = '' as $$
declare cid smallint;
begin
  select id into cid from public.api_clients
   where key_hash = p_key_hash and active and p_scope = any(scopes);
  if cid is null then return false; end if;
  update public.api_clients set last_used_at = now()
   where id = cid and (last_used_at is null or last_used_at < now() - interval '5 minutes');
  return true;
end $$;
revoke execute on function public.api_client_ok(text, text) from public, anon, authenticated;

-- Public API: key check for calc endpoints (no content returned).
create or replace function public.api_check(p_key_hash text, p_scope text default 'calc')
returns boolean language sql security definer set search_path = '' as $$
  select public.api_client_ok(p_key_hash, p_scope) $$;

-- Public API: published entries with their current revision, tags, refs and tool key.
create or replace function public.api_entries(
  p_key_hash text, p_module text default null, p_slug text default null,
  p_updated_since timestamptz default null, p_limit int default 100, p_offset int default 0)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
begin
  if not public.api_client_ok(p_key_hash, 'content') then raise exception 'invalid api key' using errcode = '28000'; end if;
  return coalesce((
    select jsonb_agg(row_to_json(x)::jsonb order by x.module, x.slug) from (
      select e.slug, e.module::text as module, e.title, e.summary, e.published_at, e.updated_at,
             s.slug as specialization, r.rev_no, r.code_edition, r.reviewed_at, r.body, r.diagram,
             (select calc_key from public.tools t where t.entry_id = e.id) as calc_key,
             (select coalesce(jsonb_agg(tg.slug order by tg.slug), '[]') from public.entry_tags et join public.tags tg on tg.id = et.tag_id where et.entry_id = e.id) as tags,
             (select coalesce(jsonb_agg(jsonb_build_object('doc', d.short_name, 'edition', d.edition, 'section', c.section_no, 'title', c.title, 'note', ref.note)), '[]')
                from public.entry_clause_refs ref join public.code_clauses c on c.id = ref.clause_id
                join public.code_documents d on d.id = c.code_document_id where ref.entry_id = e.id) as refs
        from public.entries e
        left join public.specializations s on s.id = e.specialization_id
        left join public.entry_revisions r on r.id = e.current_revision_id
       where e.status = 'published'
         and (p_module is null or e.module::text = p_module)
         and (p_slug is null or e.slug = p_slug)
         and (p_updated_since is null or e.updated_at >= p_updated_since)
       order by e.module, e.slug
       limit least(greatest(p_limit, 1), 500) offset greatest(p_offset, 0)
    ) x), '[]'::jsonb);
end $$;

-- Public API: the code clause index (own-words summaries).
create or replace function public.api_clauses(p_key_hash text, p_doc text default null)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
begin
  if not public.api_client_ok(p_key_hash, 'content') then raise exception 'invalid api key' using errcode = '28000'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('doc', d.short_name, 'edition', d.edition, 'section', c.section_no,
             'title', c.title, 'summary', c.summary, 'limits', c.limits) order by d.short_name, c.section_no)
      from public.code_clauses c join public.code_documents d on d.id = c.code_document_id
     where p_doc is null or d.short_name = p_doc), '[]'::jsonb);
end $$;

revoke execute on function public.api_check(text, text), public.api_entries(text, text, text, timestamptz, int, int), public.api_clauses(text, text) from public;
grant execute on function public.api_check(text, text), public.api_entries(text, text, text, timestamptz, int, int), public.api_clauses(text, text) to anon, authenticated;

-- In-app search (runs as the caller, so RLS decides what each user can see).
create or replace function public.search_entries(q text, max_rows int default 40)
returns table (slug text, title text, summary text, module text, status text, in_body boolean)
language sql stable security invoker set search_path = '' as $$
  select e.slug, e.title, e.summary, e.module::text, e.status::text,
         not (e.title ilike '%' || q || '%' or coalesce(e.summary, '') ilike '%' || q || '%') as in_body
    from public.entries e
    left join public.entry_revisions r on r.id = e.current_revision_id
   where length(trim(q)) >= 2
     and (e.title ilike '%' || q || '%' or coalesce(e.summary, '') ilike '%' || q || '%' or r.body::text ilike '%' || q || '%')
   order by (e.title ilike '%' || q || '%') desc, e.title
   limit least(max_rows, 100) $$;
revoke execute on function public.search_entries(text, int) from public, anon;
grant execute on function public.search_entries(text, int) to authenticated;
